LESSONS_PART = [

# ============ 第5章 C# 编程基础 (51-75) ============
{"num":51,"title":"条件语句 if / else if / else","summary":"用条件分支让程序“看情况执行”，处理各种游戏状态。","keywords":"if,else,条件语句,分支,判断","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握 if / else 语法","掌握 else if 多分支","会用条件做游戏逻辑"],
 "intro":"程序最强大的能力之一就是“看情况办事”：血量为 0 就死亡、按下按键才移动。这一切靠条件语句。",
 "sections":[
  {"h":"if / else 基础语法","lead":"最简单的判断。",
   "steps":["语法：if (条件) { 条件成立执行的代码 }","条件是一个 bool 表达式（第 50 课的比较/逻辑运算结果）。","例：if (hp <= 0) { Debug.Log(\"角色死亡\"); }","加 else：if (条件) { 成立时 } else { 不成立时 }","例：if (hp > 0) { Debug.Log(\"存活\"); } else { Debug.Log(\"死亡\"); }","else 也可以没有（只关心成立的情况）。","注意：条件一定要写在圆括号 () 里，代码块用花括号 {}。"],
   "tips":[{"t":"note","c":"单行代码可以不写花括号，但强烈建议都写，避免逻辑混乱。"}]},
  {"h":"else if 多分支","lead":"多个条件依次判断。",
   "steps":["语法：if (条件1) { } else if (条件2) { } else if (条件3) { } else { 都不满足时 }","从上到下依次判断，满足一个就执行并“跳过”后续所有分支。","例：if (score >= 90) { Debug.Log(\"S 级\"); } else if (score >= 80) { Debug.Log(\"A 级\"); } else if (score >= 60) { Debug.Log(\"B 级\"); } else { Debug.Log(\"不及格\"); }","顺序很重要：必须先写 90 再写 80，否则 95 会被 80 分支提前接住。","else 分支可省略：都不满足时什么都不做。"],
   "tips":[{"t":"warn","c":"else if 的顺序错了逻辑就全错：范围条件要“从大到小”或“从小到大”严格排列。"}]},
  {"h":"Unity 实战：状态判断","lead":"用 if 控制一个物体的行为。",
   "steps":["新建脚本 ConditionDemo，挂到 Cube 上。","在 Update 里写：if (transform.position.y < -5f) { Debug.Log(\"掉下去了！\"); }","加一个开关变量：bool isDead = false; 在 Update 里 if (isDead) { return; }（死亡后停止执行）。","结合比较：if (Input.GetKeyDown(KeyCode.Space)) { Debug.Log(\"按下了空格\"); }（输入第 8 章详讲）。","播放测试：按空格触发输出；修改 isDead 看 return 效果。","【嵌套】if 里套 if：先判断是否死亡，再判断是否按了键，体会分支结构。"],
   "tips":[{"t":"success","c":"条件语句是游戏逻辑的骨架：几乎所有“该不该做”都由它决定。"}]},
 ],
 "errors":[{"err":"if 里写 x = 5 而不是 x == 5？","why":"把赋值当成了比较","fix":"条件里一律用 == 比较；= 是赋值。"}],
 "exercise":["写一个判断等级的多分支 if","在 Update 里用 if 判断物体位置，低于阈值就打印","用 bool 开关 + if 控制是否执行某段代码"],
 "summary":"if / else / else if 已掌握。下一课学另一种分支 switch。"},

{"num":52,"title":"switch 语句","summary":"用 switch 对“多选一”场景做清晰分支，掌握 break 与 default。","keywords":"switch,case,break,default,多分支","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握 switch 语法","理解 break 的作用","会用 default 兜底"],
 "intro":"当判断的是“某个值等于什么”时，switch 比一堆 if else 更清晰。比如根据玩家选择不同职业。",
 "sections":[
  {"h":"switch 基础语法","lead":"按值跳转。",
   "steps":["语法：switch (变量) { case 值1: 代码; break; case 值2: 代码; break; default: 兜底代码; break; }","switch 根据变量的值，跳到匹配的 case 执行。","每个 case 末尾必须有 break（跳出 switch），否则会“贯穿”继续执行下一个 case。","default 处理所有未匹配的值，可省略。","例：string weapon = \"剑\"; switch (weapon) { case \"剑\": ... break; case \"弓\": ... break; default: ... break; }","switch 常与枚举（第 70 课）搭配使用，代码可读性极高。"],
   "tips":[{"t":"warn","c":"每个 case 结尾忘记 break 会“贯穿”，这是 switch 最常见的坑。"}]},
  {"h":"Unity 实战：菜单选项","lead":"根据输入数字做不同处理。",
   "steps":["新建脚本 SwitchDemo。","声明 int option = 2;（模拟玩家选择了第 2 项）。","写 switch (option) { case 1: Debug.Log(\"开始游戏\"); break; case 2: Debug.Log(\"读取存档\"); break; case 3: Debug.Log(\"设置\"); break; default: Debug.Log(\"无效选项\"); break; }","播放运行，把 option 改成不同值测试。","把 option 改成 9，观察 default 兜底输出。","体会：switch 适合“离散值多选一”，if else 适合“范围/条件判断”。"],
   "tips":[{"t":"note","c":"switch 的判断值可以是 int、string、enum、bool 等；新版还支持 switch 表达式（进阶）。"}]},
 ],
 "errors":[{"err":"报错：控制不能从 case 标签贯穿到另一个标签？","why":"case 缺 break","fix":"给每个 case 末尾补上 break。"}],
 "exercise":["用 switch 根据 1-3 打印三个菜单选项","加一个 default 处理非法输入","用 switch 处理一个 string 类型的状态"],
 "summary":"switch 已掌握。下一课进入循环：让代码重复执行。"},

{"num":53,"title":"循环：for","summary":"掌握 for 循环的三段式结构，用循环批量处理数据。","keywords":"for,循环,for循环,重复执行,计数器","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 for 语法","理解循环三要素","会用 for 批量操作"],
 "intro":"“重复做 N 次”是程序最擅长的。for 循环就是为此而生，比如生成 100 个敌人、遍历数组。",
 "sections":[
  {"h":"for 循环语法","lead":"三句话一个循环。",
   "steps":["语法：for (初始化; 条件; 更新) { 循环体 }","三个部分：① 初始化（声明计数变量，如 int i = 0）；② 条件（满足才继续，如 i < 10）；③ 更新（每轮后执行，如 i++）。","执行流程：初始化 → 检查条件 → 执行循环体 → 更新 → 再检查条件……直到条件为 false 退出。","例：for (int i = 0; i < 5; i++) { Debug.Log(i); } 输出 0,1,2,3,4（共 5 次）。","注意 i 从 0 开始、条件用 < 而不是 <=，这是“半开区间”习惯。","i 只在循环内有效（作用域）。","可以在循环体里用 i 做计算：Debug.Log(i * 2);"],
   "tips":[{"t":"note","c":"i < 5 意味着执行 5 次（0~4）。想执行 N 次就写 i < N。"}]},
  {"h":"Unity 实战：批量生成物体","lead":"用 for 一次性创建一排方块。",
   "steps":["新建脚本 ForDemo，挂到空对象上。","在 Start 里写：for (int i = 0; i < 10; i++) { GameObject cube = GameObject.CreatePrimitive(PrimitiveType.Cube); cube.transform.position = new Vector3(i * 2f, 0, 0); }","【解释】：每次循环创建一个方块，位置沿 X 轴每隔 2 米排开。","保存播放：场景里出现一排 10 个方块！","这是“动态生成”的雏形，正式实例化 Instantiate 在第 76 课。","试试改成 i * 3f 或加 Y 方向，观察变化。","【常见变形】：倒序 for (int i = 9; i >= 0; i--)、偶数步长 i += 2。"],
   "tips":[{"t":"success","c":"for + 批量创建是游戏开发的黄金组合：生成敌人、子弹、地形全用它。"}]},
 ],
 "errors":[{"err":"循环不结束（死循环）？","why":"更新语句缺失或条件恒真","fix":"确认有 i++ 更新且条件最终会不满足；否则程序卡死（Update 里尤其危险）。"}],
 "exercise":["用 for 打印 1 到 20","用 for 生成一排 5 个方块，间隔 1 米","写一个倒序 for，打印 9 到 0"],
 "summary":"for 循环已掌握。下一课学 while 与 do-while。"},

{"num":54,"title":"循环：while 与 do-while","summary":"掌握 while / do-while 循环，理解“条件式循环”的应用场景。","keywords":"while,do while,循环,条件循环,死循环","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握 while 语法","掌握 do-while 语法","理解两者的区别与应用"],
 "intro":"for 适合“知道循环几次”，while 适合“只要条件满足就一直做”。比如一直等玩家输入。",
 "sections":[
  {"h":"while 循环","lead":"先判断，后执行。",
   "steps":["语法：while (条件) { 循环体 }","只要条件为 true，就不断执行循环体；条件变为 false 时退出。","例：int i = 0; while (i < 5) { Debug.Log(i); i++; } 输出 0~4。","与 for 的等价关系：while 其实就是“去掉三段式”的 for，需要手动维护计数器。","【使用场景】不知道循环次数、只知终止条件时：如等待变量满足某条件。","【警告】条件恒 true 且无退出路径 = 死循环，程序卡死。","循环体内一定要有“改变条件”的语句（如 i++）。"],
   "tips":[{"t":"danger","c":"while 里忘了改变条件会死循环，编辑器直接卡死/报错。写 while 时先想好“怎么退出”。"}]},
  {"h":"do-while 循环","lead":"先执行一次，再判断。",
   "steps":["语法：do { 循环体 } while (条件);","无论条件真假，循环体【至少执行一次】，然后才判断条件。","例：int i = 0; do { Debug.Log(i); i++; } while (i < 3); 输出 0,1,2。","若初始条件为 false：while 一次都不执行；do-while 会执行一次。","【使用场景】“先做一次再问”的场景：如先显示一次菜单，再问是否继续。","注意 do-while 末尾有分号 ;，别漏。","对比记忆：while = 先检查再进门；do-while = 先进门再检查。"],
   "tips":[{"t":"note","c":"do-while 用得少，但“至少执行一次”的语义在某些 UI 流程里很实用。"}]},
  {"h":"Unity 实战","lead":"while 处理动态条件。",
   "steps":["新建脚本 WhileDemo，在 Start 里写：int hp = 100; while (hp > 0) { Debug.Log(\"当前血量：\" + hp); hp -= 20; }","观察输出：100,80,60,40,20，然后停止（hp 变 0 退出）。","体会 while 在“不知道要循环几次”时的便利。","再写 do-while：int n = 0; do { Debug.Log(\"执行了\" + n); n++; } while (n < 2);","对比 while (n < 2) 的版本，体会“至少执行一次”。","注意：Unity 的 Update 里尽量不要写会长时间阻塞的 while，否则游戏卡顿。"],
   "tips":[{"t":"note","c":"Update 里需要“逐帧”循环时别用 while（会卡死一帧），用 Update 本身或协程（第 82 课）。"}]},
 ],
 "errors":[{"err":"程序运行时卡死？","why":"死循环","fix":"检查 while 条件与退出语句；Update 里别写阻塞性 while。"}],
 "exercise":["用 while 打印 1 到 10","写一个 do-while，初始条件为 false 观察是否执行一次","说出 while 与 do-while 的核心区别"],
 "summary":"while / do-while 已掌握。下一课学 foreach 遍历集合。"},

{"num":55,"title":"循环：foreach 遍历","summary":"掌握 foreach 遍历集合（数组、List 等）的方法，安全简洁。","keywords":"foreach,遍历,集合,迭代,array","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握 foreach 语法","理解遍历的概念","知道 foreach 的局限性"],
 "intro":"要“把一篮子苹果挨个看一遍”就叫遍历。foreach 是遍历集合最安全的方式。",
 "sections":[
  {"h":"foreach 语法","lead":"挨个取出集合里的元素。",
   "steps":["语法：foreach (类型 变量名 in 集合) { 循环体 }","每轮循环把集合中的一个元素赋给变量，直到遍历完所有元素。","例：int[] nums = { 10, 20, 30 }; foreach (int n in nums) { Debug.Log(n); } 输出 10,20,30。","特点：不需要手动管下标、不会越界，安全简洁。","适合：数组、List、Dictionary 的键值、以及 Unity 中 FindObjectsOfType 等返回的集合。","【局限】foreach 遍历时不能修改集合元素数量（不能删除元素），否则报错。","想删除集合元素用 for 倒序遍历（第 56 课）。"],
   "tips":[{"t":"note","c":"foreach 只读遍历是首选；要改元素或删元素再考虑 for。"}]},
  {"h":"Unity 实战：遍历场景中的物体","lead":"批量处理所有同类型对象。",
   "steps":["在场景里创建 5 个 Cube（可 Ctrl+D 复制）。","新建脚本 ForeachDemo，在 Start 里写：","foreach (GameObject go in Object.FindObjectsOfType<GameObject>()) { if (go.name.StartsWith(\"Cube\")) { Debug.Log(\"找到：\" + go.name); } }","【解释】：FindObjectsOfType<GameObject>() 返回场景中所有对象，foreach 逐个处理，用条件筛出名字以 Cube 开头的。","播放运行，Console 输出所有 Cube 的名字。","简化：直接遍历数组更常见——先声明 string[] names = { \"A\", \"B\", \"C\" }; foreach 打印。","体会 foreach 在“批量处理”上的便利。"],
   "tips":[{"t":"note","c":"FindObjectsOfType 在 Update 里每帧调用很耗性能，应放 Start 或缓存，第 16 章性能课会讲。"}]},
 ],
 "errors":[{"err":"foreach 中删除元素报错：Collection was modified？","why":"遍历期间修改集合被禁止","fix":"改用 for 倒序遍历删除，或先收集再删除。"}],
 "exercise":["用 foreach 打印一个字符串数组的所有元素","遍历场景中的 5 个 Cube 并打印名字","说出 foreach 与 for 的适用场景"],
 "summary":"foreach 已掌握。下一课学 break 与 continue 控制循环。"},

{"num":56,"title":"break 与 continue 控制循环","summary":"用 break 提前退出循环、continue 跳过本轮，灵活控制循环流程。","keywords":"break,continue,退出循环,跳过,循环控制","time":"约 11 分钟","difficulty":"入门",
 "objectives":["掌握 break 用法","掌握 continue 用法","区分两者的效果"],
 "intro":"有时要在循环中途“刹车”（break）或“跳过这一轮”（continue）。本课两个小关键字解决。",
 "sections":[
  {"h":"break：提前结束循环","lead":"找到就停。",
   "steps":["break 用于【立即终止整个循环】，跳出循环体继续执行循环后面的代码。","例：for (int i = 0; i < 10; i++) { if (i == 3) break; Debug.Log(i); } 输出 0,1,2（到 3 就停）。","常用场景：在数组里“找第一个满足条件的元素”，找到就 break 节省时间。","break 只跳出最近的一层循环（嵌套时注意）。","break 也可用于 switch（第 52 课）。"],
   "tips":[{"t":"note","c":"break 是“整段停”，continue 是“只跳这一轮”——记住这个区别。"}]},
  {"h":"continue：跳过本轮","lead":"不满足条件就跳过。",
   "steps":["continue 用于【跳过当前这一轮】，立即进入下一轮循环（继续执行更新语句）。","例：for (int i = 0; i < 5; i++) { if (i % 2 == 0) continue; Debug.Log(i); } 输出 1,3（跳过偶数）。","常用场景：只处理满足条件的元素，跳过不满足的。","continue 后本轮的剩余代码不会执行。","与 break 对比：break 结束整个循环；continue 只跳过当前次。","【实际应用】在遍历敌人时跳过已死亡的敌人：if (enemy.isDead) continue;"],
   "tips":[{"t":"success","c":"continue 让循环逻辑更清晰：先“排除”不处理的，再处理剩下的。"}]},
  {"h":"Unity 实战","lead":"组合使用。",
   "steps":["新建脚本 BreakDemo，在 Start 里写：","int[] ids = { 1, 2, 3, 4, 5 };","for (int i = 0; i < ids.Length; i++) { if (ids[i] == 3) { Debug.Log(\"找到 3，停止\"); break; } Debug.Log(\"检查：\" + ids[i]); }","再写 continue 版：for (int i = 0; i < 5; i++) { if (i == 2) continue; Debug.Log(\"处理：\" + i); }","播放对比两者输出，体会 break 与 continue 的区别。","【场景】遍历生成敌人，超过上限用 break 停止；跳过已激活的用 continue。"],
   "tips":[{"t":"note","c":"嵌套循环里 break 只跳出内层，想跳出多层可用 return 或标志变量（进阶）。"}]},
 ],
 "errors":[{"err":"break 在循环外使用报错？","why":"break 只能用在循环或 switch 内","fix":"检查 break 是否误放在循环外。"}],
 "exercise":["用 for + break 找到第一个能被 7 整除的数","用 for + continue 只打印奇数","总结 break 与 continue 的区别"],
 "summary":"break / continue 已掌握。下一课学习数组 Array。"},

{"num":57,"title":"数组 Array","summary":"掌握一维数组的声明、初始化、访问与遍历，存储一组同类型数据。","keywords":"数组,array,下标,index,length,一维数组","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握数组声明与初始化","掌握下标访问元素","掌握数组遍历"],
 "intro":"要存 100 个敌人的血量，总不能建 100 个变量。数组就是“一排带编号的抽屉”。",
 "sections":[
  {"h":"数组的声明与初始化","lead":"三种写法。",
   "steps":["语法：数据类型[] 数组名; 例：int[] scores;","【初始化方式1】指定长度：int[] scores = new int[5]; // 5 个默认值 0","【初始化方式2】直接给值：int[] scores = { 90, 80, 70, 60, 50 }; // 自动确定长度","【初始化方式3】new + 值：int[] scores = new int[] { 1, 2, 3 };","数组长度固定，创建后不能增删元素。","【访问元素】用下标（索引）：scores[0] 是第一个元素，scores[1] 第二个……下标从 0 开始！","【数组长度】scores.Length 返回元素个数。","给元素赋值：scores[0] = 100;"],
   "tips":[{"t":"danger","c":"下标从 0 开始是新手第一坑：长度 5 的数组，最大下标是 4，访问 scores[5] 会越界报错。"}]},
  {"h":"遍历数组","lead":"for 与 foreach 皆可。",
   "steps":["for 遍历：for (int i = 0; i < scores.Length; i++) { Debug.Log(scores[i]); }","foreach 遍历：foreach (int s in scores) { Debug.Log(s); }","for 可以改元素（scores[i] = 0），foreach 只读。","【求和】：int sum = 0; for (...) { sum += scores[i]; }","【找最大值】：int max = scores[0]; for (...) { if (scores[i] > max) max = scores[i]; }","数组在 Unity 中常用于：配置关卡数据、存储一批点位、敌人列表等。","【多维数组】进阶：int[,] grid = new int[3,3]; 二维网格，先了解。"],
   "tips":[{"t":"note","c":"要“动态增删”的集合用 List（第 58 课），数组适合数量固定的数据。"}]},
 ],
 "errors":[{"err":"报错：IndexOutOfRangeException？","why":"访问了超出范围的下标","fix":"检查循环边界是否用了 <= 而越界；改用 scores.Length 作为上限。"}],
 "exercise":["声明一个 5 元素的 float 数组并全部赋值","用 for 求和并打印平均分","用 for 找出数组中的最大值"],
 "summary":"数组已掌握。下一课学可动态增删的 List。"},

{"num":58,"title":"List 动态列表","summary":"掌握 List 的创建、增删改查，灵活管理动态数量数据。","keywords":"list,列表,add,remove,动态数组,集合","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握 List 创建","掌握增删改查方法","理解与数组的区别"],
 "intro":"数组长度固定，但游戏中“敌人数量会变”。List 是“能自动伸缩的数组”，游戏开发使用频率极高。",
 "sections":[
  {"h":"List 基础","lead":"先学会创建与添加。",
   "steps":["List 需要引入命名空间：在脚本顶部写 using System.Collections.Generic;","创建语法：List<int> scores = new List<int>();（尖括号里是元素类型）","【添加元素】：scores.Add(90); scores.Add(80);","【获取元素个数】：scores.Count（注意是 Count 不是 Length）。","【访问元素】：scores[0] 与数组类似。","【插入】：scores.Insert(1, 85); // 在下标 1 处插入 85","【删除】：scores.Remove(90); // 删除值为 90 的第一个元素；scores.RemoveAt(0); // 按下标删除","【清空】：scores.Clear();","【判断包含】：scores.Contains(80) 返回 bool。"],
   "tips":[{"t":"note","c":"List 元素类型几乎可以是任何东西，包括 GameObject、你自己的类：List<GameObject> enemies = new List<GameObject>();"}]},
  {"h":"遍历与实战","lead":"管理一个敌人列表。",
   "steps":["遍历：foreach (int s in scores) { Debug.Log(s); } 或 for (int i = 0; i < scores.Count; i++)。","【实战】新建脚本 ListDemo：声明 List<GameObject> enemies = new List<GameObject>();","在 Start 里用 for 生成 5 个方块并加入列表：enemies.Add(GameObject.CreatePrimitive(PrimitiveType.Cube));","打印：Debug.Log(\"敌人数量：\" + enemies.Count);","删除最后一个：enemies.RemoveAt(enemies.Count - 1);","遍历打印每个敌人的名字：foreach (GameObject e in enemies) { Debug.Log(e.name); }","【注意】删除时 foreach 会报错，改用 for 倒序删除（进阶技巧）。"],
   "tips":[{"t":"success","c":"List 是游戏开发最常用的集合，务必熟练：Add / Remove / Count / 下标访问 / foreach 遍历。"}]},
 ],
 "errors":[{"err":"找不到 List 类型？","why":"缺命名空间","fix":"在脚本顶部加 using System.Collections.Generic;"}],
 "exercise":["创建一个 List<string> 添加三个玩家名字并遍历打印","在中间插入一个名字，再删除一个","用 List<GameObject> 管理场景中的物体并统计数量"],
 "summary":"List 已掌握。下一课学键值对集合 Dictionary。"},

{"num":59,"title":"字典 Dictionary","summary":"掌握 Dictionary 的“键值对”存取，高效地按名字/ID 查找数据。","keywords":"dictionary,字典,键值对,key,value,查找","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解键值对概念","掌握字典增删改查","掌握字典遍历"],
 "intro":"List 按下标找元素，但你想“按名字找数据”呢？字典（Dictionary）用“钥匙-值”配对，查找极快。",
 "sections":[
  {"h":"字典基础","lead":"“钥匙”开“抽屉”。",
   "steps":["需要 using System.Collections.Generic;","创建语法：Dictionary<string, int> scores = new Dictionary<string, int>();","尖括号里第一个是“键 Key”类型，第二个是“值 Value”类型。","【添加】：scores[\"小明\"] = 90; 或 scores.Add(\"小红\", 85);","【取值】：int s = scores[\"小明\"]; // 得 90","【判断键存在】：scores.ContainsKey(\"小明\") 返回 bool，取之前先判断防报错。","【删除】：scores.Remove(\"小红\");","【元素个数】：scores.Count。","【改值】：scores[\"小明\"] = 95;（键已存在则覆盖）。"],
   "tips":[{"t":"danger","c":"取不存在的键（scores[\"不存在\"]) 会抛异常崩溃！取值前先用 ContainsKey 判断。"}]},
  {"h":"遍历与实战","lead":"遍历键值对。",
   "steps":["遍历所有键值对：foreach (KeyValuePair<string, int> kv in scores) { Debug.Log(kv.Key + \"：\" + kv.Value); }","或遍历所有键：foreach (string name in scores.Keys) { ... }；遍历所有值：scores.Values。","【实战】游戏物品背包：Dictionary<string, int> inventory = new Dictionary<string, int>();","inventory[\"金币\"] = 100; inventory[\"药水\"] = 5;","加金币：inventory[\"金币\"] += 50;","打印背包内容：foreach (var kv in inventory) { Debug.Log(kv.Key + \" x\" + kv.Value); }","【适合场景】按名字查配置、玩家数据、成就表等。","字典内部无序，遍历顺序不保证插入顺序。"],
   "tips":[{"t":"note","c":"用 var 可以简化声明：foreach (var kv in inventory)。var 让编译器推断类型。"}]},
 ],
 "errors":[{"err":"报错：KeyNotFoundException？","why":"取了不存在的键","fix":"取值前用 ContainsKey 判断，或用 TryGetValue（更高效）。"}],
 "exercise":["创建一个 Dictionary<string,int> 存 3 个物品数量","给“金币”增加 100 并打印","遍历打印所有键值对"],
 "summary":"字典已掌握。下一课学字符串 String 的常用操作。"},

{"num":60,"title":"字符串 String 常用操作","summary":"掌握字符串的拼接、比较、截取、替换、查找与格式化，处理文本数据。","keywords":"字符串,string,拼接,截取,replace,substring,format","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握字符串拼接与比较","掌握截取与查找","掌握格式化输出"],
 "intro":"玩家名字、对话文本、日志信息都是字符串。本课把 String 最常用的操作一网打尽。",
 "sections":[
  {"h":"拼接与比较","lead":"把文字组合、比较。",
   "steps":["【拼接】用 + ：string full = \"你好\" + \"世界\"; 得 \"你好世界\"。","数字自动转字符串：string msg = \"分数：\" + 100; 得 \"分数：100\"。","【频繁拼接用 StringBuilder】（性能更好）：using System.Text; StringBuilder sb = new StringBuilder(); sb.Append(\"a\"); sb.Append(\"b\");","【比较相等】：str1 == str2 返回 bool（比较内容）。","【忽略大小写比较】：str1.Equals(str2, System.StringComparison.OrdinalIgnoreCase)。","【是否包含】：str.Contains(\"世界\") 返回 bool。"],
   "tips":[{"t":"note","c":"循环里大量用 + 拼字符串会消耗性能，用 StringBuilder 代替（第 16 章优化讲）。"}]},
  {"h":"截取、替换、查找与格式化","lead":"文本加工四件套。",
   "steps":["【长度】：str.Length。","【截取】：str.Substring(1) 从下标 1 截到末尾；str.Substring(1, 3) 从 1 开始截 3 个字符。","【替换】：str.Replace(\"好\", \"棒\") 把所有“好”换成“棒”。","【查找下标】：str.IndexOf(\"世界\") 返回首次出现位置，找不到返回 -1。","【转大写/小写】：str.ToUpper() / str.ToLower()。","【去空格】：str.Trim() 去掉首尾空格。","【拆分】：string[] parts = str.Split(','); 按逗号拆成数组。","【格式化】：string.Format(\"你好，{0}！你的分数是 {1}\", name, score)；或插值 string msg = $\"你好，{name}！分数 {score}\";（推荐，更直观）。","格式化用于动态生成文本、UI 显示数据等，非常常用。"],
   "tips":[{"t":"success","c":"插值字符串 $\"...{变量}...\" 比 + 拼接更清晰，推荐优先使用。"}]},
  {"h":"Unity 实战","lead":"处理 UI 文本。",
   "steps":["新建脚本 StringDemo。","string name = \"玩家\"; int score = 250;","用插值生成：string msg = $\"{name} 的分数是 {score}\"; Debug.Log(msg);","截取练习：string s = \"HelloUnity\"; Debug.Log(s.Substring(0, 5)); // Hello","替换：Debug.Log(s.Replace(\"Unity\", \"C#\")); // HelloC#","拆分：string data = \"1,2,3,4\"; string[] arr = data.Split(','); foreach (var a in arr) Debug.Log(a);","播放观察输出。","实际应用中常把变量拼进 UI 文本：uiText.text = $\"血量：{hp}\";（第 167 课）"],
   "tips":[{"t":"note","c":"字符串是不可变对象：每次 + 都会创建新字符串，所以频繁拼接用 StringBuilder。"}]},
 ],
 "errors":[{"err":"Substring 越界报错？","why":"起始位置超出长度","fix":"先判断 str.Length 再截取，或用安全的 Substring(0, Math.Min(len, str.Length))。"}],
 "exercise":["用插值拼出\"我是 XX，今年 XX 岁\"","把一个句子中的某个词替换掉","把\"苹果,香蕉,橘子\"拆分并逐个打印"],
 "summary":"字符串操作已掌握。下一课学习方法的定义与调用。"},

{"num":61,"title":"方法（函数）的定义与调用","summary":"掌握方法的声明、调用与作用，把代码“打包”成可复用模块。","keywords":"方法,函数,method,void,定义,调用","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解方法的作用","掌握方法的定义与调用","养成模块化思维"],
 "intro":"重复的代码写一遍就行——用方法把逻辑“打包”，需要时调用。这让代码整洁又可复用。",
 "sections":[
  {"h":"什么是方法","lead":"一段“有名字的指令块”。",
   "steps":["方法（Method/函数）把一段逻辑封装起来，起个名字，需要时“调用”它。","好处：代码复用（一处定义、多处调用）、逻辑清晰、易维护。","Unity 里 Start()、Update() 就是系统自动调用的方法；我们也可以自己定义。","自己定义方法的语法：访问修饰符 返回类型 方法名(参数列表) { 方法体 }","例：void SayHello() { Debug.Log(\"你好\"); }","【调用】：SayHello(); 直接写方法名加括号。","调用时，程序跳进方法体执行，执行完回到调用处继续。","方法名用大驼峰：StartGame、TakeDamage。"],
   "tips":[{"t":"note","c":"方法命名要“动词”化（做什么）：MovePlayer、AttackEnemy。"}]},
  {"h":"定义与调用实战","lead":"写一个方法并调用。",
   "steps":["新建脚本 MethodDemo，在类里（Start 外面）定义一个方法：","void ShowMessage() { Debug.Log(\"这是自定义方法输出\"); }","在 Start 里调用三次：ShowMessage(); ShowMessage(); ShowMessage();","播放：输出三行日志。","再定义一个带“功能”的方法：void AddScore() { score += 10; Debug.Log(\"分数：\" + score); }","声明字段 int score = 0; 在 Start 里调用 AddScore() 两次。","体会：方法把“加 10 分并显示”打包成一个动作。","方法里可以调用其他方法：void A() { B(); } void B() { Debug.Log(\"B\"); }"],
   "tips":[{"t":"success","c":"凡是“会重复出现的逻辑”都提成方法：一处修改，处处生效。"}]},
 ],
 "errors":[{"err":"方法没被调用就“不执行”？","why":"方法定义后不会自动运行","fix":"方法需要被调用才执行：在 Start/Update 或其他方法里写上 方法名();"}],
 "exercise":["定义一个 SayHello 方法并在 Start 里调用 3 次","定义一个方法完成两数相加并打印","在方法里调用另一个方法，体会嵌套调用"],
 "summary":"方法已掌握。下一课学参数与返回值，让方法更灵活。"},

{"num":62,"title":"方法参数与返回值","summary":"掌握带参数的方法与返回值，让方法“接收输入、产出结果”。","keywords":"参数,parameter,返回值,return,重载","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握参数传递","掌握 return 返回值","了解方法重载"],
 "intro":"上节课的方法只会“自说自话”。有了参数，方法能“按需处理不同数据”；有了返回值，方法能“把结果交回来”。",
 "sections":[
  {"h":"方法参数","lead":"给方法“喂数据”。",
   "steps":["参数在方法名后的括号里声明：void Greet(string name) { Debug.Log(\"你好，\" + name); }","调用时传入实参：Greet(\"小明\"); Greet(\"小红\");","可声明多个参数，用逗号分隔：void Attack(int damage, string target) { ... }","调用：Attack(10, \"怪物\");","参数的类型、顺序必须与定义一致。","【可选参数】给参数默认值：void Show(int a, int b = 5) —— 调用 Show(3) 时 b 自动为 5。","【参数作用域】参数只在方法内部有效。"],
   "tips":[{"t":"note","c":"参数让方法通用：一个方法处理所有玩家，而不是给每个玩家写一个方法。"}]},
  {"h":"返回值 return","lead":"方法“交回结果”。",
   "steps":["返回类型不再是 void，而是要返回的类型：int Add(int a, int b) { return a + b; }","方法体内用 return 返回结果；执行到 return 立即结束方法。","调用时把结果接住：int result = Add(3, 4); // result = 7","返回类型为 void 时不能用 return 带值，但可以裸 return 提前结束方法。","【返回字符串】string GetName() { return \"英雄\"; }","【多个返回点】if 分支里各自 return。","例：string GetRank(int s) { if (s >= 90) return \"S\"; if (s >= 60) return \"B\"; return \"F\"; }"],
   "tips":[{"t":"warn","c":"有返回类型的方法，所有分支都必须有 return，否则编译报错。"}]},
  {"h":"方法重载与实战","lead":"同名方法不同参数。",
   "steps":["方法重载（Overload）：同一个类里允许同名方法，但参数列表必须不同（数量或类型）。","例：void Heal(int amount) { ... } 和 void Heal(int amount, float rate) { ... } 同时存在合法。","调用时根据传入参数自动选择对应版本。","【实战】新建脚本 MethodParamDemo：","int Add(int a, int b) { return a + b; }","float Add(float a, float b) { return a + b; } // 重载","void TakeDamage(int dmg) { hp -= dmg; Debug.Log(\"剩余：\" + hp); }","int hp = 100;","在 Start 里：Debug.Log(Add(3, 4)); Debug.Log(Add(1.5f, 2.5f)); TakeDamage(30);","播放查看输出，体会参数、返回值与重载。"],
   "tips":[{"t":"success","c":"好的方法“黑盒化”：调用方只需关心输入与输出，不用管内部实现。"}]},
 ],
 "errors":[{"err":"报错：并非所有代码路径都返回值？","why":"某些分支没有 return","fix":"检查所有分支（尤其 else）都补上 return。"}],
 "exercise":["写一个带参数方法：给任意名字打招呼","写一个计算面积并返回 float 的方法","为你的方法写一个重载版本"],
 "summary":"参数与返回值已掌握。下一课进入面向对象：类与对象。"},

{"num":63,"title":"类 Class 与对象","summary":"理解面向对象的核心：用“类”描述类型，用“对象”实例化，建立数据+行为模型。","keywords":"类,class,对象,实例化,面向对象,new","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解类的概念","掌握创建对象 new","理解字段与方法组合"],
 "intro":"C# 是面向对象语言。类是“图纸”，对象是“按图纸造出的实物”。Unity 里的每个组件其实都是类。",
 "sections":[
  {"h":"类与对象的关系","lead":"“图纸”与“实物”。",
   "steps":["【类 Class】：定义一种事物的“模板/图纸”，描述它有什么数据（字段）和能做什么（方法）。","【对象 Object/实例】：根据类“new 出来”的具体实体，有自己独立的数据。","例：定义一个 Player 类（有名字、血量字段，有攻击方法）；new 出两个玩家对象，各有各的血量。","类定义语法：public class 类名 { 字段; 方法; }","创建对象：类名 变量名 = new 类名();","访问对象成员：对象名.字段名 / 对象名.方法名()。","Unity 脚本类继承 MonoBehaviour，但普通的数据类可以不继承（用来存数据、写逻辑）。"],
   "tips":[{"t":"note","c":"一句话：类 = 图纸，对象 = 用图纸造出的实物，可造无数个。"}]},
  {"h":"定义一个类并使用","lead":"动手造一个“玩家”类。",
   "steps":["在 Project/Scripts 里创建 C# 脚本，命名为 PlayerData（注意文件名=类名）。","把内容改成（不继承 MonoBehaviour，作为普通数据类）：","public class PlayerData { public string name; public int hp = 100; public void SayHello() { UnityEngine.Debug.Log(name + \"：你好！\"); } }","保存，等待编译。","再创建脚本 PlayerTest（继承 MonoBehaviour）挂到空对象上，在 Start 里写：","PlayerData p1 = new PlayerData(); p1.name = \"小明\"; p1.hp = 80;","PlayerData p2 = new PlayerData(); p2.name = \"小红\"; p2.hp = 120;","p1.SayHello(); p2.SayHello(); Debug.Log(p1.hp);","播放：两个玩家各自输出自己的名字。","体会：同一张图纸（类）造出两个独立对象。"],
   "tips":[{"t":"note","c":"不继承 MonoBehaviour 的类不能挂到对象上，但可以作为“数据容器”在脚本里使用，这是游戏开发常用手法。"}]},
 ],
 "errors":[{"err":"创建脚本后没有挂载选项？","why":"脚本类不继承 MonoBehaviour","fix":"普通数据类本身不能挂；让它继承 MonoBehaviour 或作为字段在别的脚本里 new 使用。"}],
 "exercise":["定义一个 Enemy 类（字段：名字、血量；方法：受伤）","创建两个敌人对象，各自设定血量","调用方法让它们分别报出自己的血量"],
 "summary":"类与对象已掌握。下一课学构造函数。"},

{"num":64,"title":"构造函数 Constructor","summary":"掌握构造函数：创建对象时自动执行的初始化方法，带参初始化对象。","keywords":"构造函数,constructor,初始化,new,this","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解构造函数的作用","掌握带参构造函数","掌握 this 关键字"],
 "intro":"每次 new 对象时，如果希望“一出生就带数据”，用构造函数。它是对象的“出生仪式”。",
 "sections":[
  {"h":"构造函数基础","lead":"对象创建时自动执行。",
   "steps":["构造函数是与类同名、没有返回类型的方法。","语法：public 类名() { 初始化代码 }","创建对象 new 类名() 时，构造函数自动执行一次。","例：public class Player { public int hp; public Player() { hp = 100; } }","这样 new Player() 时 hp 自动为 100。","如果类里没写构造函数，编译器会提供默认无参构造。","构造函数也可以有参数：public Player(int startHp) { hp = startHp; }","调用：Player p = new Player(200);"],
   "tips":[{"t":"note","c":"构造函数不能有返回类型（连 void 都不能写），名字必须与类名完全一致。"}]},
  {"h":"this 关键字与实战","lead":"指代“当前对象”。",
   "steps":["【this】在方法/构造内指代“当前正在操作的这个对象”。","主要用于区分“参数名与字段名相同”的情况：","public Player(int hp) { this.hp = hp; } // this.hp 是字段，hp 是参数","【多个构造】重载：public Player() { hp = 100; } public Player(int hp) { this.hp = hp; }","两个都写，调用时可选无参或带参版本。","【构造链】一个构造调用另一个：public Player() : this(100) { }","【实战】在 PlayerData 类里加构造函数：","public PlayerData(string n, int h) { name = n; hp = h; }","然后：PlayerData p = new PlayerData(\"小明\", 80); 一步完成创建+初始化。","体会构造函数让“创建即就绪”。"],
   "tips":[{"t":"success","c":"带参构造 + 直接传值初始化，比“先 new 再逐个赋值”更优雅、更不易漏。"}]},
 ],
 "errors":[{"err":"报错：构造函数缺少参数？","why":"写了带参构造后，无参调用失败","fix":"显式再加一个无参构造，或调用时传入参数。"}],
 "exercise":["给 Enemy 类添加带参构造函数（名字+血量）","用一句 new Enemy(\"野猪\", 50) 创建并初始化","用 this 区分字段与参数"],
 "summary":"构造函数已掌握。下一课学封装的访问修饰符与属性。"},

{"num":65,"title":"封装：public/private 与属性","summary":"掌握访问修饰符与属性（Property），保护数据、控制外部访问。","keywords":"封装,public,private,属性,property,get,set","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解 public/private","掌握属性的 get/set","养成封装习惯"],
 "intro":"类的字段应该“谁能看、谁能改”要有规矩，这就是封装。它是面向对象的三大特性之一（封装、继承、多态）。",
 "sections":[
  {"h":"访问修饰符","lead":"控制“谁能访问”。",
   "steps":["【public 公有】：任何地方都能访问（类外也能读写字段）。","【private 私有】：只有类内部能访问（类外不可见），默认权限。","【protected 受保护】：本类及子类可访问（继承时用，第 66 课）。","【internal】等：较少用，先忽略。","例：public int hp; // 外部可直接改；private int secret; // 外部不可见。","字段默认是 private（若没写修饰符，实际是 private）。","直接 public 字段的缺点：外部可以随意改成非法值（如血量负数）。"],
   "tips":[{"t":"note","c":"原则：数据尽量 private，通过方法/属性提供受控访问，这叫“数据封装”。"}]},
  {"h":"属性 Property","lead":"“受控的门卫”。",
   "steps":["属性用 get（取值）/ set（赋值）控制字段的访问逻辑。","语法：public int Hp { get { return hp; } set { hp = value; } }","【value】是 set 里系统给的“要赋的新值”。","只读属性：只写 get 不写 set（外部不能改）。","自动属性：public int Score { get; set; } 编译器自动生成隐藏字段。","【逻辑校验】：public int Hp { get { return hp; } set { hp = value < 0 ? 0 : value; } } // 防止负数","在 set 里可加限制、通知等逻辑，这是 public 字段做不到的。","使用：player.Hp = 50; int h = player.Hp; 用法与字段一样。"],
   "tips":[{"t":"success","c":"字段私有 + 属性公开 = 既安全又好用，是专业代码的标准写法。"}]},
  {"h":"Unity 实战","lead":"在脚本里运用封装。",
   "steps":["新建脚本 EncapsulationDemo，定义：","private int hp = 100;","public int Hp { get { return hp; } set { hp = Mathf.Clamp(value, 0, 200); } }","public bool IsDead { get { return hp <= 0; } } // 只读属性","在 Start 里测试：Hp = 500; Debug.Log(Hp); // 被限制为 200","Hp = -50; Debug.Log(Hp); // 被限制为 0","Debug.Log(IsDead); // True","播放观察：属性把值限制在合法范围。","体会封装的价值：外部无法破坏数据规则。"],
   "tips":[{"t":"note","c":"Mathf.Clamp(value, min, max) 是 Unity 提供的“夹取”函数，把值限制在区间内，非常好用。"}]},
 ],
 "errors":[{"err":"类外访问 private 字段报错？","why":"私有字段外部不可见","fix":"把字段改为 public 或通过 public 属性/方法访问。"}],
 "exercise":["把字段设为 private，用属性控制读写","给属性加一个值范围限制","写一个只读属性（如 IsDead）"],
 "summary":"封装已掌握。下一课学面向对象的第二个特性：继承。"},

{"num":66,"title":"继承 Inheritance","summary":"掌握类的继承，让子类复用父类的数据与方法，理解“is-a”关系。","keywords":"继承,inheritance,父类,子类,base,override","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解继承的概念","掌握子类定义","掌握 base 关键字"],
 "intro":"“敌人”和“Boss”有很多共同点，没必要写两遍。继承让子类“继承”父类的一切，还能增加自己的特色。",
 "sections":[
  {"h":"继承的概念","lead":"“子承父业”。",
   "steps":["继承：子类自动拥有父类的字段、方法、属性。","语法：class 子类 : 父类 { 自己的内容 }","例：class Animal { public void Eat() { ... } }  class Dog : Animal { public void Bark() { ... } }","Dog 对象既能调用 Eat（继承自 Animal），也能调用 Bark（自己的）。","继承表达“is-a”关系：狗“是一种”动物。","【单继承】C# 一个类只能有一个父类（但可实现多个接口，第 68 课）。","父类也叫基类（Base），子类也叫派生类（Derived）。","所有类最终都继承自 object。"],
   "tips":[{"t":"note","c":"继承是“复用 + 扩展”：把公共逻辑放父类，差异化放子类。"}]},
  {"h":"Unity 继承实战","lead":"用继承管理不同敌人。",
   "steps":["创建脚本 Enemy（不继承 MonoBehaviour，作为数据基类）：","public class Enemy { public string name = \"敌人\"; public int hp = 100; public void TakeDamage(int dmg) { hp -= dmg; } public virtual void ShowInfo() { Debug.Log(name + \" HP:\" + hp); } }","创建脚本 Boss : Enemy：","public class Boss : Enemy { public Boss() { name = \"Boss\"; hp = 500; } public override void ShowInfo() { Debug.Log(\"BOSS! \" + name + \" HP:\" + hp); } }","创建测试脚本继承 MonoBehaviour，在 Start 里：","Enemy e = new Enemy(); Boss b = new Boss();","e.TakeDamage(10); b.TakeDamage(100);","e.ShowInfo(); b.ShowInfo(); // 各自输出","播放：Boss 类继承并覆盖了父类行为。","【virtual + override】父类方法标 virtual 才能被子类 override 重写（第 67 课细讲）。"],
   "tips":[{"t":"warn","c":"子类看不到父类的 private 成员；用 protected 让子类可访问（第 65 课）。"}]},
 ],
 "errors":[{"err":"override 报错：没有可重写的方法？","why":"父类方法没标 virtual","fix":"在父类方法前加 virtual 关键字。"}],
 "exercise":["定义 Animal 基类与 Dog、Cat 子类","让子类继承父类方法并添加自己的方法","用 protected 字段让子类可以访问"],
 "summary":"继承已掌握。下一课学多态与虚方法。"},

{"num":67,"title":"多态 Polymorphism 与虚方法","summary":"理解多态：父类引用指向子类对象，调用同一方法呈现不同行为。","keywords":"多态,virtual,override,虚方法,父类引用","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解多态的概念","掌握 virtual/override","会用父类引用处理子类"],
 "intro":"“同一个动作，不同对象表现不同”：所有敌人都会“攻击”，但普通怪和 Boss 攻击方式不同。这就是多态。",
 "sections":[
  {"h":"虚方法与重写","lead":"“可被改写的钩子”。",
   "steps":["【virtual 虚方法】父类方法标 virtual，允许子类重写。","【override 重写】子类用 override 提供自己的实现。","例：class Animal { public virtual void Speak() { Debug.Log(\"动物叫\"); } }","class Dog : Animal { public override void Speak() { Debug.Log(\"汪汪\"); } }","class Cat : Animal { public override void Speak() { Debug.Log(\"喵喵\"); } }","创建对象调用 Speak()：Dog 输出汪汪，Cat 输出喵喵。","核心：调用的是“同一个方法名”，但根据实际对象类型执行不同实现。"],
   "tips":[{"t":"note","c":"virtual + override 是多态的基础：父类定义“接口”，子类提供“实现”。"}]},
  {"h":"父类引用指向子类对象","lead":"多态的经典写法。",
   "steps":["父类类型的变量可以指向子类对象：Animal a = new Dog();","调用 a.Speak() 时，实际执行的是 Dog 的 Speak（多态生效）。","【好处】用一个父类数组装所有子类：Animal[] zoo = { new Dog(), new Cat() };","foreach (Animal a in zoo) { a.Speak(); } // 依次汪汪、喵喵","以后新增一个 Bird 类继承 Animal 并 override Speak，zoo 代码不用改就能处理它——这就是“开闭原则”。","这非常适合游戏里的“对象管理”：用一个 Enemy 列表管理普通怪和 Boss。"],
   "tips":[{"t":"success","c":"多态让代码“面向父类编程”，扩展新类型时不改旧代码，是专业架构的核心。"}]},
  {"h":"Unity 实战","lead":"多态管理敌人。",
   "steps":["沿用上节课的 Enemy / Boss 类（Speak 换成 Attack 逻辑即可）。","在测试脚本里写：","Enemy[] enemies = { new Enemy(), new Boss(), new Enemy() };","foreach (Enemy en in enemies) { en.TakeDamage(50); en.ShowInfo(); }","播放：列表里的对象各自按自己的类型响应。","体会：一个数组、一个循环，管理了不同类型的敌人。","【注意】若父类没标 virtual 而子类想重写，会报错或静默隐藏，务必标 virtual。"],
   "tips":[{"t":"note","c":"多态三要素：继承 + virtual/override + 父类引用。三者缺一不可。"}]},
 ],
 "errors":[{"err":"调用子类特有方法报错？","why":"父类引用看不到子类新增方法","fix":"把引用类型设为子类，或用类型判断转型（如 if (en is Boss)）——进阶。"}],
 "exercise":["定义 Animal 基类与两个子类，各自 override Speak","用父类数组存储子类对象并循环调用","说出多态的三个条件"],
 "summary":"多态已掌握。下一课学接口 Interface。"},

{"num":68,"title":"接口 Interface","summary":"掌握接口：定义“能力契约”，让无关的类统一行为，支持多实现。","keywords":"接口,interface,契约,implements,多实现","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解接口的概念","掌握接口定义与实现","区分接口与继承"],
 "intro":"接口是“能力合同”：规定“你必须会这些”，但不管“你怎么做”。比如“会飞的”可以是鸟，也可以是飞机。",
 "sections":[
  {"h":"接口的概念与定义","lead":"只声明，不实现。",
   "steps":["接口（Interface）声明“类必须提供哪些方法/属性”，但不写具体实现。","定义语法：interface 接口名 { 返回类型 方法名(参数); }","接口名习惯以 I 开头：IFlyable、IDamageable。","例：interface IDamageable { void TakeDamage(int dmg); }","接口里的方法默认是 public 且没有方法体。","接口不能被实例化（不能 new）。","类实现接口：class 类名 : 接口名 { 实现所有方法 }","类实现接口后，必须实现接口里声明的全部成员，否则编译报错。"],
   "tips":[{"t":"note","c":"接口是“能力标签”：IDamageable 表示“可以被伤害”，与“你是什么类”无关。"}]},
  {"h":"接口 vs 继承 & 实战","lead":"多实现与统一处理。",
   "steps":["【区别】继承是“is-a”（狗是动物）；接口是“can-do”（能飞、能受伤）。","【多实现】一个类只能继承一个父类，但可以实现多个接口：class Bird : Animal, IFlyable, IDamageable。","【实战】定义接口：","interface IDamageable { void TakeDamage(int dmg); }","让两个不同类实现它：class Player : IDamageable { public void TakeDamage(int dmg) { ... } } class Enemy : IDamageable { public void TakeDamage(int dmg) { ... } }","用一个接口数组统一管理：IDamageable[] targets = { new Player(), new Enemy() };","foreach (var t in targets) { t.TakeDamage(10); }","统一调用“受伤”逻辑，不管对象是玩家还是敌人。","【接口也支持多态】接口引用指向实现类对象。"],
   "tips":[{"t":"success","c":"接口让“不同的类”有“相同的能力”，是设计“子弹可以打任何物体”这类逻辑的利器。"}]},
 ],
 "errors":[{"err":"报错：未实现接口成员？","why":"类实现了接口却没实现全部方法","fix":"补全接口声明的所有方法（签名需完全一致）。"}],
 "exercise":["定义 IDamageable 接口","让 Player 和 Enemy 都实现它","用接口数组统一对它们造成伤害"],
 "summary":"接口已掌握。下一课学命名空间与 using。"},

{"num":69,"title":"命名空间与 using","summary":"掌握命名空间的组织作用、using 引用、解决同名冲突。","keywords":"命名空间,namespace,using,冲突,组织代码","time":"约 11 分钟","difficulty":"入门",
 "objectives":["理解命名空间作用","掌握 using 引用","了解自定义命名空间"],
 "intro":"脚本顶部的 using System.Collections.Generic; 是干嘛的？本课讲清楚命名空间与 using，以及代码“找得着东西”的机制。",
 "sections":[
  {"h":"命名空间是什么","lead":"代码的“抽屉分类”。",
   "steps":["命名空间（namespace）用于把相关类归组，避免不同库里的同名类冲突。","例：UnityEngine 命名空间里有 Transform、Vector3 等；System 命名空间里有 Console 等。","全名写法：UnityEngine.Debug.Log(...) 才是完整路径。","【using 指令】把命名空间“引入”，之后就能直接用短名：using UnityEngine; 之后直接写 Debug.Log(...)。","Unity 脚本自动带 using System; using System.Collections; using System.Collections.Generic; using UnityEngine;","【冲突】两个命名空间都有同名类时，用全名区分：System.Console 与 UnityEngine.Debug 不冲突。","UnityEngine.Debug.Log 与 Debug 有歧义时会报错，用全名解决。"],
   "tips":[{"t":"note","c":"using 只是“省打字”，不是把代码复制进来。"}]},
  {"h":"自定义命名空间与实战","lead":"组织你自己的代码。",
   "steps":["自定义命名空间：在类外面包一层 namespace MyGame { public class Player { } }","使用时：用 using MyGame; 或写全名 MyGame.Player。","【实战】打开你的 PlayerData 脚本，在其顶部加：namespace MyGame { ... 把类包进去 ... }","保存编译。","在 PlayerTest 脚本顶部加 using MyGame;","这样 PlayerTest 里 new PlayerData() 依然可用（通过 using）。","若不加 using，就得写 new MyGame.PlayerData()。","体会命名空间对大型项目的组织价值：不同模块（战斗、UI）放不同命名空间。","【规范】项目常用命名空间：游戏名 + 模块名，如 MyGame.Combat。"],
   "tips":[{"t":"warn","c":"给类加命名空间后，若其他脚本没 using 也没写全名，会报“找不到类型”——记得引用。"}]},
 ],
 "errors":[{"err":"报错：找不到类型或命名空间？","why":"缺少 using 或写错命名空间","fix":"检查类所在的命名空间，在引用处加 using 或用全名。"}],
 "exercise":["说出 3 个 Unity 自动带的 using 是干什么的","给自己的类加一个自定义命名空间并引用它"],
 "summary":"命名空间已掌握。下一课学枚举与结构体。"},

{"num":70,"title":"枚举 enum 与结构体 struct","summary":"掌握枚举（命名常量集合）与结构体（轻量数据容器），让代码更清晰。","keywords":"枚举,enum,结构体,struct,常量组","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握枚举定义与使用","掌握结构体定义与使用","理解与类的区别"],
 "intro":"“星期几”“方向”“敌人状态”这类固定选项，用枚举最清晰；“坐标点”这类小数据包，用结构体最轻量。",
 "sections":[
  {"h":"枚举 enum","lead":"一组有名字的常量。",
   "steps":["枚举定义一组固定的命名整数值。","定义语法：public enum 枚举名 { 值1, 值2, 值3 }","例：public enum Direction { Up, Down, Left, Right }","使用：Direction d = Direction.Up;","内部每个值对应整数（默认从 0 开始）：Up=0, Down=1……","可用 switch 处理枚举：switch (d) { case Direction.Up: ... break; }","【作用】避免魔法数字、提高可读性、IDE 智能提示友好。","游戏常用：敌人状态（Idle/Patrol/Attack）、角色状态、武器类型。","【指定值】public enum State { Idle = 0, Attack = 1, Dead = 99 }"],
   "tips":[{"t":"note","c":"枚举定义位置：类外（命名空间内）或类内均可；类外更通用。"}]},
  {"h":"结构体 struct","lead":"轻量的“值类型”数据包。",
   "steps":["结构体（struct）与类类似，可含字段和方法，但它是“值类型”。","定义：public struct Point { public float x; public float y; public Point(float a, float b) { x = a; y = b; } }","使用：Point p = new Point(1, 2);","【与类的区别】类=引用类型（赋值共享同一个对象）；结构体=值类型（赋值是复制一份）。","结构体适合“小而简单”的数据（坐标、颜色、尺寸），性能更好。","Unity 的 Vector3、Color、Quaternion 其实就是结构体。","【实战】struct WeaponStats { public int damage; public float speed; }","WeaponStats sword = new WeaponStats(); sword.damage = 10;","体会结构体适合做“值包”（如存档的某一小段数据）。"],
   "tips":[{"t":"note","c":"何时用 struct：数据量小、偏值语义、频繁创建销毁（性能友好）；复杂对象用 class。"}]},
 ],
 "errors":[{"err":"枚举值转 int 报错？","why":"枚举与 int 不自动互转","fix":"显式转换：(int)Direction.Up 或 (Direction)2。"}],
 "exercise":["定义一个敌人状态的枚举并用 switch 处理","定义一个 Point 结构体并创建使用","说出 enum 与 struct 各自最适合的场景"],
 "summary":"枚举与结构体已掌握，C# 语法基本齐了。下一课回到 Unity 专有话题：脚本生命周期。"},

{"num":71,"title":"Unity 脚本生命周期（Awake/Start/Update）","summary":"掌握 Unity 脚本的自动调用顺序：Awake、Start、Update、OnDestroy 等。","keywords":"生命周期,awake,start,update,ondestroy,执行顺序","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握核心生命周期方法","理解各方法的调用时机","知道哪个方法放哪类代码"],
 "intro":"Unity 会在特定时机自动调用脚本里的一些“特殊方法”，这就是生命周期。搞懂它们，代码才会“在对的时候做对的事”。",
 "sections":[
  {"h":"核心生命周期方法","lead":"按时间顺序记忆。",
   "steps":["【Awake()】：对象创建/脚本加载时最先调用，只调用一次。适合：获取组件引用、初始化变量（早于一切）。","【OnEnable()】：对象每次被启用时调用（包括 Awake 之后、首次显示时）。","【Start()】：在第一次 Update 之前调用一次，在 Awake 之后。适合：初始化依赖其他对象的数据、读取存档。","【Update()】：每帧调用一次。适合：需要每帧持续执行的逻辑（移动、检测）。","【LateUpdate()】：每帧在 Update 之后调用。适合：跟随相机的更新（在角色移动完成后）。","【FixedUpdate()】：固定时间间隔调用（默认 0.02 秒），物理计算用（第 72 课）。","【OnDisable()】：对象被禁用时调用。","【OnDestroy()】：对象被销毁时调用。适合：清理资源、保存数据。","【OnApplicationQuit()】：退出游戏时调用。"],
   "tips":[{"t":"note","c":"顺序速记：Awake → OnEnable → Start → (FixedUpdate/Update/LateUpdate 循环) → OnDisable → OnDestroy。"}]},
  {"h":"生命周期实战","lead":"打印全部执行时机。",
   "steps":["新建脚本 LifecycleDemo 挂到空对象上，在 Awake/Start/Update/LateUpdate/OnDisable/OnDestroy 里分别写 Debug.Log(\"方法名\")。","播放运行，观察 Console 的顺序。","你会看到：Awake → OnEnable → Start → Update（每帧）→ LateUpdate（每帧）。","停止播放，观察 OnDisable → OnDestroy 输出。","尝试：在 Inspector 取消勾选脚本组件（禁用），观察 OnDisable 触发。","再勾选启用，观察 OnEnable 再次触发。","【实操要点】Awake 里 GetComponent 获取引用；Start 里使用引用；Update 里每帧逻辑。","多脚本时，Awake 先于所有 Start 执行（保证引用先就绪）。"],
   "tips":[{"t":"success","c":"铁律：获取引用放 Awake/Start，每帧逻辑放 Update，物理放 FixedUpdate。"}]},
 ],
 "errors":[{"err":"Update 里每帧 GetComponent 导致卡顿？","why":"每帧查找组件很耗","fix":"在 Awake 里把组件存成字段，Update 直接用缓存。"}],
 "exercise":["打印完整的生命周期顺序","把 GetComponent 从 Update 移到 Awake 并对比性能","体验禁用/启用脚本触发 OnEnable/OnDisable"],
 "summary":"生命周期已掌握。下一课深挖 Update 与 FixedUpdate 的区别。"},

{"num":72,"title":"Update 与 FixedUpdate 的区别","summary":"理解帧率相关与固定时间步长的区别，知道物理计算该放哪。","keywords":"update,fixedupdate,帧率,固定时间步长,物理,deltaTime","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解两者调用频率差异","知道物理放 FixedUpdate","理解时间步长概念"],
 "intro":"为什么物体移动的代码放 Update，而物理（力、碰撞）放 FixedUpdate？本课讲透两者背后的原理。",
 "sections":[
  {"h":"Update：每帧一次","lead":"跟“帧”走，帧率波动。",
   "steps":["Update 每一帧调用一次。","调用频率 = 帧率（FPS）：60 FPS 时每秒 60 次，30 FPS 时每秒 30 次。","所以 Update 的执行次数“不固定”——取决于电脑性能。","适合：几乎所有的“非物理”游戏逻辑（输入响应、UI、动画、移动计算）。","由于频率不固定，Update 里做移动时必须乘以 Time.deltaTime（第 74 课），否则速度随帧率变化。","Update 里不适合直接施加物理力（会受帧率影响）。"],
   "tips":[{"t":"note","c":"Update 的频率 = 看设备脸色；FixedUpdate 的频率 = 恒定。"}]},
  {"h":"FixedUpdate：固定时间步长","lead":"跟“时间”走，恒定节奏。",
   "steps":["FixedUpdate 以【固定时间间隔】调用，默认每 0.02 秒一次（每秒 50 次）。","这个间隔由 Project Settings→Time→Fixed Timestep 控制，与帧率无关。","即使游戏掉帧，FixedUpdate 依然按固定节奏推进。","【物理系统】刚体（Rigidbody）的运动、力、碰撞检测都在 FixedUpdate 阶段计算。","因此：对刚体施加力、改变速度应放在 FixedUpdate 里（或刚体相关代码），保证物理稳定。","【注意】FixedUpdate 可能一帧内调用多次（掉帧时补算），也可能 0 次。","Debug.Log 在 FixedUpdate 里会“一坨一坨”输出，属正常。","【小结】移动物体（不涉及刚体力）用 Update；物理力与刚体操作用 FixedUpdate。"],
   "tips":[{"t":"warn","c":"在 FixedUpdate 里操作普通 Transform 移动也应乘 Time.fixedDeltaTime（第 74 课会统一讲时间增量）。"}]},
  {"h":"实战验证","lead":"观察调用次数。",
   "steps":["新建脚本 TimeDemo，挂到空对象。","声明两个计数变量：int u=0, f=0;","Update 里 u++；FixedUpdate 里 f++。","每隔一秒打印一次（用 Time.time 判断）：if (Time.time > last + 1f) { Debug.Log($\"Update:{u} FixedUpdate:{f}\"); last = Time.time; u = 0; f = 0; }","播放观察：一秒钟里 FixedUpdate 约 50 次，Update 次数取决于你的帧率。","在 Project Settings→Time 里把 Fixed Timestep 改成 0.05，再观察 FixedUpdate 次数减半。","体会两者的节奏差异。"],
   "tips":[{"t":"note","c":"改回默认 0.02，避免影响后续物理实验。"}]},
 ],
 "errors":[{"err":"物体在 Update 里受力后表现不稳定？","why":"物理计算应放 FixedUpdate","fix":"把 AddForce 等刚体操作移到 FixedUpdate。"}],
 "exercise":["用计数器对比每秒 Update 与 FixedUpdate 次数","把 Fixed Timestep 改为 0.05 观察变化","总结两者的适用场景"],
 "summary":"Update 与 FixedUpdate 已掌握。下一课系统学习调试神器 Debug.Log。"},

{"num":73,"title":"Debug.Log 调试输出","summary":"掌握 Debug 系列方法：Log/Warning/Error、格式化输出、条件输出，高效调试。","keywords":"debug.log,调试,日志,debug.warning,debug.error","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握 Debug 系列方法","学会输出变量与对象","了解调试技巧"],
 "intro":"Debug.Log 是你排查问题的最强武器。本课把它用到极致。",
 "sections":[
  {"h":"Debug 系列方法","lead":"三种级别 + 高级用法。",
   "steps":["【Debug.Log(内容)】：输出普通信息（白色图标）。适合确认“代码执行到这里了”、“这个值是多少”。","【Debug.LogWarning(内容)】：输出警告（黄色图标），适合提示“值可能异常但还能跑”。","【Debug.LogError(内容)】：输出错误（红色图标），适合“这里不该发生”的严重问题。","内容可以是：数字、字符串、变量、对象：Debug.Log(playerName); Debug.Log(gameObject);","【多个参数】Debug.Log(\"名字：\", player);","【条件输出】Debug.Log(条件表达式)，始终输出；想要“满足条件才输出”可用 if 包一层。","【带颜色的富文本】Debug.Log(\"<color=red>危险！</color>\"); 文字变红（部分平台支持）。"],
   "tips":[{"t":"note","c":"三种级别在 Console 里颜色/图标不同，一眼分辨问题严重性。"}]},
  {"h":"调试实战技巧","lead":"高效排查问题的套路。",
   "steps":["【定位问题】在关键节点打点：方法开头打印\"进入 TakeDamage\"、结尾打印\"伤害结算\"，确认流程是否走通。","【输出变量值】计算前后各打一行，对比中间变化：Debug.Log($\"之前:{hp} 之后:{hp - dmg}\");","【输出对象引用】Debug.Log(target, target); 第二个参数传对象，点击日志可在 Hierarchy 高亮该对象。","【帧调试】在 Update 里打印位置：Debug.Log(transform.position); 观察每帧数值。","【画线调试】（进阶）Debug.DrawLine/ DrawRay 在场景里画线，直观看到方向与碰撞。","【条件断点】Console 顶部“Collapse”与暂停功能配合使用。","【清理】调试完记得删除多余的 Log，避免发布后刷屏与性能损耗。"],
   "tips":[{"t":"success","c":"Debug 心法：先确认“有没有到这”→ 再确认“值对不对”→ 最后确认“为什么变这样”。"}]},
 ],
 "errors":[{"err":"发布后 Console 看不到日志？","why":"发布版默认不显示编辑器 Console","fix":"发布版日志在系统日志文件；调试在编辑器里看即可。"}],
 "exercise":["用三种级别各输出一条日志","打印一个变量的中间变化过程","用富文本把一条日志标红"],
 "summary":"Debug 系列已掌握。下一课学最关键的时间增量 Time.deltaTime。"},

{"num":74,"title":"Time.deltaTime 帧间隔时间","summary":"理解并运用 Time.deltaTime，让移动与数值变化与帧率无关、跨设备一致。","keywords":"timedeltatime,deltaTime,帧率无关,时间,time.time","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解 deltaTime 的含义","掌握移动必乘 deltaTime","掌握 Time.time 等时间 API"],
 "intro":"这是新手 90% 都会犯的错：物体移动“忽快忽慢”。解药就是 Time.deltaTime。本课彻底讲透。",
 "sections":[
  {"h":"问题：帧率不同速度不同","lead":"先看错误示范。",
   "steps":["错误写法（新手常见）：Update 里写 transform.position += new Vector3(1, 0, 0);","意思是“每帧移动 1 米”：60 帧电脑每秒动 60 米，30 帧电脑每秒动 30 米！","同样代码在不同电脑上速度差一倍——这就是“帧率相关”的 bug。","【根因】Update 每帧调用，但帧率不固定，直接用“每帧固定值”就会随帧率漂移。","【解法】把“每帧的值”换算成“每秒的值”，乘以 Time.deltaTime。"],
   "tips":[{"t":"danger","c":"Update 里所有“位移、加减速度、数值增减”都要乘 Time.deltaTime，这是铁律！"}]},
  {"h":"Time.deltaTime 是什么","lead":"“上一帧花了几秒”。",
   "steps":["Time.deltaTime = 从上一帧到当前帧所经过的时间（单位秒）。","60 FPS 时约 0.0167 秒；30 FPS 时约 0.033 秒。","【正确写法】transform.position += new Vector3(5f, 0, 0) * Time.deltaTime;","含义：每秒移动 5 米。无论帧率高低，一秒钟移动的总距离都是 5 米。","原理：高速率时每次乘的小（次数多），低帧率时每次乘的大（次数少），乘积趋同。","【其他时间 API】Time.time：游戏运行总时长；Time.fixedDeltaTime：固定步长（物理用）；Time.timeScale：时间缩放（第 248 课）。","【时间缩放】改 Time.timeScale 可做慢动作，但 FixedUpdate 受 fixedDeltaTime 影响。"],
   "tips":[{"t":"note","c":"deltaTime 单位是秒，所以“数值”表示“每秒多少”。写代码时把单位默认为“每秒”就对了。"}]},
  {"h":"实战验证","lead":"对比写与不写。",
   "steps":["新建脚本 DeltaDemo 挂到 Cube 上。","先写错误版：在 Update 里 transform.position += Vector3.right;","播放观察 Cube 移动速度；打开帧率显示（Stats 面板或看控制台）体会速度。","改成正确版：transform.position += Vector3.right * Time.deltaTime;","现在速度是每秒 1 米，播放观察明显变慢且稳定。","把数值改成 5f：transform.position += Vector3.right * 5f * Time.deltaTime; 每秒 5 米。","加一个计时：Debug.Log(Time.time); 在 Update 里，观察每秒输出。","【补充】Unity 里还有更专业的移动方式（transform.Translate），也会配合 deltaTime（第 81 课）。"],
   "tips":[{"t":"success","c":"看到“position/velocity += ”就想到 * Time.deltaTime，形成条件反射。"}]},
 ],
 "errors":[{"err":"物体移动“一顿一顿”？","why":"可能是乘法写错位置或值过大","fix":"确认乘的是 Time.deltaTime 而非 Time.time；数值单位按“每秒”设置。"}],
 "exercise":["写一段每秒移动 3 米的代码","对比写与不写 deltaTime 的速度差异","用 Time.time 实现每 2 秒打印一次"],
 "summary":"Time.deltaTime 已掌握，这是跨设备一致性的关键。下一课进入向量 Vector3。"},

{"num":75,"title":"向量 Vector3 基础","summary":"理解三维向量：方向与大小、向量运算、常用向量属性，操控 3D 空间。","keywords":"vector3,向量,方向,大小,magnitude,normalized,坐标","time":"约 16 分钟","difficulty":"入门",
 "objectives":["理解向量的含义","掌握向量加减与缩放","掌握常用向量属性"],
 "intro":"3D 世界的移动、朝向、距离全是向量。本课把 Vector3 讲透，它是 Unity 开发的地基。",
 "sections":[
  {"h":"什么是向量","lead":"“有方向、有大小”的量。",
   "steps":["Vector3 表示三维空间中的一个向量/坐标，三个分量 (x, y, z)。","在 Unity 中常用 new Vector3(x, y, z) 创建：new Vector3(1, 0, 0) 表示“向右 1 米”。","【两种理解】① 位置：世界中的一个点坐标；② 方向/位移：从一点指向另一点的“箭头”。","transform.position 是一个 Vector3（位置）；两个位置相减得到位移向量。","【常用常量】Vector3.zero = (0,0,0)；Vector3.one = (1,1,1)；Vector3.up = (0,1,0)；Vector3.forward = (0,0,1)；Vector3.right = (1,0,0)。","这些常量超常用：想让物体“向上移动”就用 Vector3.up。"],
   "tips":[{"t":"note","c":"Vector3.up（向上）、forward（向前）、right（向右）是世界方向，写代码离不开它们。"}]},
  {"h":"向量运算","lead":"加减、缩放、距离。",
   "steps":["【加法】位移叠加：new Vector3(1,0,0) + new Vector3(0,1,0) = (1,1,0)（斜着走）。","【减法】两点之差 = 从 B 指向 A 的方向：Vector3 dir = a.position - b.position;","【缩放】向量 × 数字：Vector3.up * 5f = 向上移动 5 米。","【长度 Magnitude】向量的大小：dir.magnitude 返回距离（米）。","【距离快捷】Vector3.Distance(a, b) 直接算两点距离。","【单位化 Normalized】方向不改变、长度变成 1：dir.normalized。","用法：需要“方向”时用 normalized，需要“距离”时用 magnitude。","例：Dir 规范化后 × 速度 × deltaTime = 匀速朝目标移动。"],
   "tips":[{"t":"success","c":"“两点相减得方向，normalized 得朝向，magnitude 得距离”——三句话背下来。"}]},
  {"h":"Unity 实战","lead":"让方块朝目标移动。",
   "steps":["场景里放两个 Cube：A（红色）在原点，B（蓝色）在 (5, 0, 3)。","新建脚本 VectorDemo 挂到 A 上。","在 Update 里写：","Vector3 dir = transform.position - target.position; // 指向目标的向量","float dist = dir.magnitude; // 距离","Debug.Log(\"距离：\" + dist);","dir = dir.normalized; // 单位方向","transform.position += dir * 5f * Time.deltaTime; // 每秒向目标靠近 5 米","target 用 public Transform 字段（第 84 课序列化）在 Inspector 拖入 B。","播放：A 匀速朝 B 移动！","这就是“追踪/移动”的雏形，第 80-81 课会系统讲组件 API。"],
   "tips":[{"t":"note","c":"距离小于某阈值（如 0.5）就停止移动，加上这个判断更真实（追击停止逻辑）。"}]},
 ],
 "errors":[{"err":"移动方向不对（反了）？","why":"向量减法顺序反了","fix":"a - b 是从 b 指向 a；想“朝目标移动”就用 target - self。"}],
 "exercise":["计算两个物体之间的距离并打印","用 normalized + 速度实现匀速移动","说出 magnitude 与 normalized 的区别"],
 "summary":"Vector3 基础已掌握，C# 篇过半。下一课进入“游戏对象与组件交互”，开始让对象活起来！"},
]
